/** Transitions game from idle to running. No-op if already started or game is over. */
export function startGame(state: GameState): GameState {
  if (state.isStarted || state.isGameOver) return state;
  return { ...state, isStarted: true, isPaused: false };
}

/** Toggles pause/resume. No-op if game hasn't started or is over. */
export function togglePause(state: GameState): GameState {
  if (state.isGameOver || !state.isStarted) return state;
  return { ...state, isPaused: !state.isPaused };
}
