/** Returns the lowest valid row for the active piece (ghost/shadow position). */
export function getGhostRow(state: GameState): number {
// /[worker-ants] generated by AI Agent (2026-03-16 20:17:17)
  let ghostRow = state.activePiece.row;
  while (isValidPosition(state.board, state.activePiece.shape, ghostRow + 1, state.activePiece.col)) {
    ghostRow++;
  }
  return ghostRow;
}

